From 508adc1dff78dca72ba050b1aaa14a0092468581 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:30:24 +0100
Subject: [PATCH] applets/devicenotifier: add an option to only mount removable
 devices

Clicking an unmounted removable device always mounted it and opened it
in the file manager. A new context menu option lets that button only
mount the device, and moves "Mount and Open" to the expanded actions.

BUG: 468200
---
 .../actions/mountandopenaction.cpp              |  6 ++++++
 .../devicenotifier/actions/mountandopenaction.h |  2 ++
 applets/devicenotifier/actionsinfo.cpp          |  6 ++++++
 applets/devicenotifier/actionsinfo.h            |  6 +++++-
 applets/devicenotifier/main.xml                 |  4 ++++
 applets/devicenotifier/qml/DeviceItem.qml       | 17 +++++++++++------
 applets/devicenotifier/qml/main.qml             |  8 ++++++++
 7 files changed, 42 insertions(+), 7 deletions(-)

diff --git a/applets/devicenotifier/actions/mountandopenaction.cpp b/applets/devicenotifier/actions/mountandopenaction.cpp
index 454bba10f8..eb48415215 100644
--- a/applets/devicenotifier/actions/mountandopenaction.cpp
+++ b/applets/devicenotifier/actions/mountandopenaction.cpp
@@ -124,6 +124,12 @@ QString MountAndOpenAction::text() const
     return m_text;
 }

+bool MountAndOpenAction::isMountAndOpen() const
+{
+    return m_hasStorageAccess && m_storageInfo->isRemovable() && !m_isRoot && !m_stateInfo->isMounted()
+        && !(m_stateInfo->isChecked() && m_stateInfo->needRepair()) && !m_supportedProtocols.contains(u"mtp");
+}
+
 void MountAndOpenAction::triggered()
 {
     qCDebug(APPLETS::DEVICENOTIFIER) << "Mount And Open action triggered";
diff --git a/applets/devicenotifier/actions/mountandopenaction.h b/applets/devicenotifier/actions/mountandopenaction.h
index 39ce3816d0..eedeec88e1 100644
--- a/applets/devicenotifier/actions/mountandopenaction.h
+++ b/applets/devicenotifier/actions/mountandopenaction.h
@@ -31,6 +31,8 @@ public:
     QString icon() const override;
     QString text() const override;

+    bool isMountAndOpen() const;
+
 private Q_SLOTS:
     void updateAction();
     void deviceStateChanged();
diff --git a/applets/devicenotifier/actionsinfo.cpp b/applets/devicenotifier/actionsinfo.cpp
index 92cf83679a..c1775049f7 100644
--- a/applets/devicenotifier/actionsinfo.cpp
+++ b/applets/devicenotifier/actionsinfo.cpp
@@ -47,6 +47,7 @@ ActionsInfo::ActionsInfo(const std::shared_ptr<StorageInfo> &storageInfo, const

     connect(m_defaultAction, &ActionInterface::iconChanged, this, &ActionsInfo::defaultActionIconChanged);
     connect(m_defaultAction, &ActionInterface::textChanged, this, &ActionsInfo::defaultActionTextChanged);
+    connect(m_defaultAction, &ActionInterface::textChanged, this, &ActionsInfo::defaultActionIsMountAndOpenChanged);

     qCDebug(APPLETS::DEVICENOTIFIER) << "Actions Info " << m_storageInfo->device().udi() << " : Initializing complete";
 }
@@ -76,6 +77,11 @@ QString ActionsInfo::defaultActionText() const
     return m_defaultAction->text();
 }

+bool ActionsInfo::defaultActionIsMountAndOpen() const
+{
+    return m_defaultAction->isMountAndOpen();
+}
+
 int ActionsInfo::rowCount(const QModelIndex &parent) const
 {
     if (parent.isValid()) {
diff --git a/applets/devicenotifier/actionsinfo.h b/applets/devicenotifier/actionsinfo.h
index 21b44d72d2..a2a8af7ea9 100644
--- a/applets/devicenotifier/actionsinfo.h
+++ b/applets/devicenotifier/actionsinfo.h
@@ -15,6 +15,7 @@
 #include "stateinfo.h"
 #include "storageinfo.h"

+class MountAndOpenAction;
 class PredicatesMonitor;

 class ActionsInfo : public QAbstractListModel
@@ -26,6 +27,7 @@ class ActionsInfo : public QAbstractListModel
     Q_PROPERTY(QString defaultActionName READ defaultActionName CONSTANT)
     Q_PROPERTY(QString defaultActionIcon READ defaultActionIcon NOTIFY defaultActionIconChanged)
     Q_PROPERTY(QString defaultActionText READ defaultActionText NOTIFY defaultActionTextChanged)
+    Q_PROPERTY(bool defaultActionIsMountAndOpen READ defaultActionIsMountAndOpen NOTIFY defaultActionIsMountAndOpenChanged)

 public:
     enum ActionInfo {
@@ -54,6 +56,7 @@ private:
     QString defaultActionName() const;
     QString defaultActionIcon() const;
     QString defaultActionText() const;
+    bool defaultActionIsMountAndOpen() const;

     void updateActionsForPredicates(const QHash<QString, Solid::Predicate> &predicates);

@@ -63,6 +66,7 @@ private:
 Q_SIGNALS:
     void defaultActionIconChanged(const QString &icon);
     void defaultActionTextChanged(const QString &text);
+    void defaultActionIsMountAndOpenChanged();

     void unmountActionIsValidChanged(const QString &udi, bool status);

@@ -75,7 +79,7 @@ private Q_SLOTS:

 private:
     bool m_isEmpty;
-    ActionInterface *m_defaultAction;
+    MountAndOpenAction *m_defaultAction;
     ActionInterface *m_unmountAction;
     QList<ActionInterface *> m_actions;
     QHash<QString, std::pair<int, ActionInterface *>> m_notValidActions;
diff --git a/applets/devicenotifier/main.xml b/applets/devicenotifier/main.xml
index 26c9e5e6f3..0bba473f8b 100644
--- a/applets/devicenotifier/main.xml
+++ b/applets/devicenotifier/main.xml
@@ -22,6 +22,10 @@
       <label>If true it tries to open the plasmoid when a new device is inserted, as a kind of notification.</label>
       <default>true</default>
     </entry>
+    <entry name="openAfterMount" type="Bool">
+      <label>If true, clicking a removable device that is not mounted mounts it and opens it in the file manager; if false, it only mounts it.</label>
+      <default>true</default>
+    </entry>
   </group>

 </kcfg>
diff --git a/applets/devicenotifier/qml/DeviceItem.qml b/applets/devicenotifier/qml/DeviceItem.qml
index e1b0258e2e..e8f2295f67 100644
--- a/applets/devicenotifier/qml/DeviceItem.qml
+++ b/applets/devicenotifier/qml/DeviceItem.qml
@@ -12,6 +12,7 @@ pragma ComponentBehavior: Bound
 import QtQuick
 import QtQuick.Controls as QQC2

+import org.kde.plasma.plasmoid
 import org.kde.plasma.extras as PlasmaExtras
 import org.kde.plasma.components as PlasmaComponents3
 import org.kde.kirigami as Kirigami
@@ -39,6 +40,8 @@ PlasmaExtras.ExpandableListItem {
     property bool hasMessage: deviceItem.deviceMessage !== ""

     //Shows true whenever the device is idle and present in the system.
+    readonly property bool mountOnly: !Plasmoid.configuration.openAfterMount && (deviceItem.deviceActions?.defaultActionIsMountAndOpen ?? false)
+
     readonly property bool isFree: !deviceItem.deviceIsBusy && deviceItem.deviceState !== StateInfo.NotPresent

     //Shows true whenever the device finished some job
@@ -131,13 +134,13 @@ PlasmaExtras.ExpandableListItem {

     QQC2.Action {
         id: defaultAction
-        icon.name: deviceItem.deviceActions?.defaultActionIcon ?? ""
-        text: deviceItem.deviceActions?.defaultActionText ?? ""
+        icon.name: deviceItem.mountOnly ? "media-mount" : deviceItem.deviceActions?.defaultActionIcon ?? ""
+        text: deviceItem.mountOnly ? i18n("Mount") : deviceItem.deviceActions?.defaultActionText ?? ""
         onTriggered: {
             if (deviceItem.deviceMounted) {
                 unmountTimer.restart();
             }
-            deviceItem.deviceActions.actionTriggered(deviceItem.deviceActions.defaultActionName);
+            deviceItem.deviceActions.actionTriggered(deviceItem.mountOnly ? "Mount" : deviceItem.deviceActions.defaultActionName);
         }
     }

@@ -159,9 +162,11 @@ PlasmaExtras.ExpandableListItem {
             delegate: PlasmaComponents3.ToolButton {
                 required property var model //TODO rename model roles and split

+                readonly property bool isMountAndOpen: deviceItem.mountOnly && model.Name === "Mount"
+
                 width: parent.width
-                text: model.Text
-                icon.name: model.Icon
+                text: isMountAndOpen ? deviceItem.deviceActions.defaultActionText : model.Text
+                icon.name: isMountAndOpen ? deviceItem.deviceActions.defaultActionIcon : model.Icon

                 KeyNavigation.up: actionRepeater.currentIndex > 0 ? actionRepeater.itemAtIndex(actionRepeater.currentIndex - 1) : deviceItem
                 KeyNavigation.down: {
@@ -173,7 +178,7 @@ PlasmaExtras.ExpandableListItem {
                 }

                 onClicked: {
-                    deviceItem.deviceActions.actionTriggered(model.Name);
+                    deviceItem.deviceActions.actionTriggered(isMountAndOpen ? deviceItem.deviceActions.defaultActionName : model.Name);
                 }
             }
         }
diff --git a/applets/devicenotifier/qml/main.qml b/applets/devicenotifier/qml/main.qml
index dffc3778b0..39f06a1e6f 100644
--- a/applets/devicenotifier/qml/main.qml
+++ b/applets/devicenotifier/qml/main.qml
@@ -186,6 +186,14 @@ PlasmoidItem {
                 Plasmoid.configuration.popupOnNewDevice = checked;
             }
         },
+        PlasmaCore.Action {
+            text: i18n("Open in file manager after mounting")
+            checkable: true
+            checked: Plasmoid.configuration.openAfterMount
+            onTriggered: checked => {
+                Plasmoid.configuration.openAfterMount = checked;
+            }
+        },
         PlasmaCore.Action {
             isSeparator: true
         }
-- 
2.53.0
